        triple2 = col_vals[20:23] if len(col_vals) >= 23 else None
        if triple1 and all(v > 1 for v in triple1):
            print(f"Col {col}: rows 19-21 = {triple1}, rows 20-22 = {triple2}")

# Let me check which input columns correspond to output patterns
